import { createGlobalStyle } from 'styled-components';
import '../fonts/Nunito-Regular.tff'

const GlobalStyles = createGlobalStyle`

    @import url('https://fonts.googleapis.com/css2?family=Nunito:wght@400;700&family=Source+Sans+Pro:ital@0;1&display=swap');

    *,
    *::after,
    *::before {
        margin: 0px;
        padding: 0px;
        box-sizing: inherit;
    }

    html {
        font-size: 62.5%
    }

    body {
        box-sizing: border-box;
        font-family: 'Nunito';
    }
`;

export default GlobalStyles;
